etape_suivi() {
  say "État des sites communaux et dernier import de chaque conseil, tels que les Pages du dépôt de données les publient :"
  py "$PAGES_DONNEES" <<'PY' || warn "etat-sources.json ou conseils/import.json illisible"
import sys
import httpx

base = sys.argv[1]
etat = httpx.get(f"{base}/etat-sources.json", timeout=30).raise_for_status().json()["sources"]
imports = httpx.get(f"{base}/conseils/import.json", timeout=30).raise_for_status().json()
rattrapes = imports.get("rattrapages", {})
sites = {cle: e for cle, e in etat.items() if cle.startswith("site-")}
for cle, e in sorted(sites.items()):
    conseil = cle.removeprefix("site-")
    importe = imports["conseils"].get(conseil, "jamais importé")
    rattrape = f" · rattrapé {rattrapes[conseil]}" if conseil in rattrapes else ""
    print(f"  {cle:<10} {e['etat']:<12} {e.get('motif') or '':<20} {importe}{rattrape}")
disponibles = sum(e["etat"] == "disponible" for e in sites.values())
print(f"  {disponibles} sites disponibles sur {len(sites)}")
PY
  say ""
  say "Issues ouvertes du dépôt de données :"
  gh issue list -R "$REPO_DONNEES" --state open --json number,title,labels \
    -q '.[] | "  #\(.number) \(.title) [\([.labels[].name] | join(","))]"'
  note "Une issue « Panne : Quicksite » ou « Import en échec : Quicksite » à tort se ferme au passage qui la contredit ;"
  note "relancer cette étape demain matin, après le premier import du jour (scripts/mise-en-ligne-j3-quicksite.sh 10)."
  valider "Sondes Quicksite disponibles, 25 communes importées, i-web toujours importé, aucune issue à tort ?"
  suite
}

